    "definition": "Serotonin (5-hydroxytryptamin, 5-HT) je klíčový neurotransmiter a lokální hormon syntetizovaný z L-tryptofanu, který prostřednictvím široké rodiny receptorů (5-HT1 až 5-HT7) reguluje náladu, spánek, krevní tlak, hemostázu a motilitu GIT.",
