    "pearl": "Při anafylaktickém šoku je podání H1-antihistaminik (či glukokortikoidů) jako léků první volby závažnou chybou! Tyto látky mají pomalý nástup účinku a nedokážou zvrátit život ohrožující bronchospasmus a těžkou hypotenzi. Jediným lékem zachraňujícím život je ADRENALIN podaný intramuskulárně (i.m.) do anterolaterální části stehna, který působí jako okamžitý funkční antagonista histaminu!",
