    "pearl": "Kombinace NSAIDs (např. ibuprofenu) s ACE-inhibitory a diuretiky představuje tzv. 'Triple Whammy' (trojitý úder) na ledviny, který může vyvolat akutní selhání ledvin (AKI)! Diuretika snižují cirkulující objem, ACEi dilatují eferentní arteriolu (snižují filtrační tlak v glomerulu) a NSAIDs blokádou prostaglandinů kontrahují aferentní arteriolu. Filtrace v ledvinách se tím téměř zastaví!",
