      "  - Dlouhodobě působící (poločas > 24 hod): diazepam, flunitrazepam, klonazepam. Metabolizují se oxidací v játrech na aktivní metabolity s extrémně dlouhým poločasem.",
      "Oxazepam a lorazepam se metabolizují pouze přímou konjugací s kyselinou glukuronovou, jsou proto bezpečnější u pacientů s cirhózou a u seniorů."
