      "Zvyšují afinitu receptoru k GABA a zvyšují frekvenci otevírání chloridového kanálu. Tok chloridových iontů ($Cl^-$) do buňky vyvolá hyperpolarizaci membrány a sníží dráždivost neuronu.",
      "Mají stropový efekt (bezpečné v monoterapii), ale v kombinaci s alkoholem nebo opioidy dochází k synergické depresi dechového centra."
