          "Správně! Bupivakain (Marcain) se velmi pevně váže na sodíkové kanály myokardu během akčního potenciálu. Způsobuje těžkou depresi vedení vzruchu a komorové tachyarytmie refrakterní k resuscitaci. Antidotum je lipidová emulze (lipid sink).",
