      "Intravenózní podání se musí provádět velmi pomalu za monitorace TK, hrozí kritický pokles tlaku (hypotenzní šok).",
      "Kontraindikace: hypertrofie prostaty, glaukom s uzavřeným úhlem, mechanická obstrukce GIT."
