    "pearl": "Rychlá intravenózní aplikace Algifenu (nebo samotného metamizolu) může vyvolat těžkou, život ohrožující hypotenzi (ne-alergenní anafylaktoidní reakci s kolapsem oběhu). Injekce musí být podávána vleže a extrémně pomalu (rychlostí maximálně 1 ml za minutu) za stálé kontroly tlaku a tepu pacienta!",
