          "Správně! Methotrexát je antimetabolit folátu. Kyselina listová podaná s časovým odstupem (aby neblokovala účinek MTX na lymfocyty v den podání) chrání buňky střevního traktu a kostní dřeně.",
          "Nesprávně. MTX se u RA podává převážně p.o. nebo s.c. jednou týdně.",
