          "Správně! Kolchicin je alkaloid z ocúnu jesenního. Vazbou na tubulin zastavuje polymeraci mikrotubulů, což paralyzuje cytoskelet neutrofilů. Ty pak nedokážou fagocytovat krystaly močové kyseliny a uvolňovat zánětlivé interleukiny (IL-1beta).",
