          "Správně! Pseudocholinesteráza běžně zničí sukcinylcholin velmi rychle. Pacienti s autozomálně recesivním deficitem tohoto enzymu nedokážou lék odbourat a zůstávají paralyzovaní a závislí na ventilaci, dokud účinek samovolně nevyprchá.",
          "Nesprávně. Kyslík neovlivňuje metabolismus myorelaxancií.",
          "Nesprávně. Nervus phrenicus není lékem strukturálně poškozován, je pouze funkčně zablokován."
