      "  - $NO$ stimuluje guanylate cyklázu, zvyšuje cGMP, což vede k defosforylaci lehkého řetězce myosinu a relaxaci svaloviny.",
      "  - Dominantně dilatují žíly (venodilatace - snižují preload - plnění srdce, čímž klesá napětí stěny a spotřeba kyslíku) a ve vyšších dávkách dilatují i velké tepny.",
      "Ostatní antianginózní léky:",
