      "Spironolakton: srdeční selhání (remodelace), jaterní cirhóza s ascitem, primární hyperaldosteronismus (Connův syndrom). Nežádoucí účinek spironolaktonu: gynekomastie u mužů (blokuje i androgenní receptory; eplerenon je selektivnější).",
