      "  - **Statiny** (atorvastatin, rosuvastatin): kompetitivní inhibitory HMG-CoA reduktázy (klíčový enzym syntézy cholesterolu v hepatocytech). Pokles cholesterolu vede k up-regulaci LDL-receptorů na hepatocytech a zvýšenému vychytávání LDL z krve. Stabilizují aterosklerotické pláty.",
      "  - **Ezetimib**: selektivně inhibuje transportér NPC1L1 v kartáčovém lemu tenkého střeva, čímž blokuje vstřebávání cholesterolu z potravy a žluče.",
      "  - **PCSK9 inhibitory** (monoklonální protilátky alirokumab, evolokumab; sirna inklisiran): blokují protein PCSK9, který normálně degraduje LDL-receptory. Výsledkem je masivní zmnožení LDL-receptorů a pokles LDL o 50-60 %.",
      "  - **Fibráty** (fenofibrát): agonisté receptorů PPAR-alfa. Zvyšují aktivitu lipoproteinové lipázy, dominují ve snižování triglyceridů a zvyšování HDL.",
      "Antiobezitika:",
      "  - **Agonisté receptoru GLP-1** (liraglutid, semaglutid): zpomalují vyprazdňování žaludku a stimulují centrum sytosti v hypothalamu.",
      "  - Orlistat: inhibitor žaludeční a pankreatické lipázy (brání štěpení a absorpci tuků z potravy - nežádoucí účinek: steatorea)."
