      "    - ADP ($P2Y_{12}$) antagonisté: **Clopidogrel, Prasugrel** (ireversibilní); **Ticagrelor** (reversibilní). Blokují signalizaci ADP, což brání aktivaci GP IIb/IIIa receptorů.",
      "    - Inhibitory GP IIb/IIIa receptorů: abciximab (blokují finální agregaci destiček vazbou na fibrinogen).",
      "  - Fibrinolytika (Altepláza, tenektepláza): rekombinantní tkáňový aktivátor plasminogenu (rtPA). Konvertuje plasminogen vázaný v trombu na plasmin, který degraduje fibrin.",
      "  - Hemostatika:",
      "    - Antifibrinolytika (Kyselina tranexamová, PAMBA): kompetitivně blokují vazebná místa pro lysin na plasminogenu, čímž brání jeho vazbě na fibrin a stabilizují sraženinu.",
