      "    - **Antagonisté NK1 receptoru** (aprepitant): blokují receptor pro substanci P v centru zvracení (neurokinin-1). Účinné u odloženého zvracení po chemoterapii.",
      "    - **Antagonisté D2 receptorů** (itoprid, metoklopramid, thiethylperazin): tlumí spouštěcí zónu chemoreceptorů v prodloužené míše.",
      "    - **H1 antihistaminika / Anticholinergika** (moxastin teoklát - Kinedryl, scopolamin): tlumí vestibulární dráhy ( kinetózy - cestovní nevolnost).",
      "  - Prokinetika:",
      "    - **Metoklopramid**: antagonista $D_2$ a agonista $5-HT_4$ (zvyšuje uvolnění ACh ve stěně střeva). Prochází HEB (riziko extrapyramidových příznaků - diskinezí u dětí/starých).",
      "    - **Itoprid**: antagonista $D_2$ a inhibitor acetylcholinesterázy. Neprochází HEB (bezpečnější, nevyvolává EPS)."
