          "Správně! U invazivních infekcí tělo potřebuje patogen vyprázdnit. Zpomalením pasáže se prodlouží kontakt bakterií se sliznicí, což usnadní invazi a perforaci střeva.",
          "Nesprávně. Chemická inkompatibilita není důvodem kontraindikace.",
          "Nesprávně. Horečku loperamin přímo nezvyšuje, ale může zhoršit infekční stav, který k ní vede."
