          "Správně! Kyselé prostředí střeva také tlumí růst amoniak-produkujících bakterií. Pacient má mít 2-3 měkké stolice denně k zajištění kontinuální eliminace dusíkatých toxinů.",
          "Nesprávně. Laktulóza nemá antivirové účinky.",
