          "Nesprávně. Loperamid peristaltiku výrazně zpomaluje.",
          "Správně! Racekadotril (Hidrasec) je proléčivo racekadotrilátu. Zabraňuje rozpadu endogenních opioidů (enkefalinů) v GIT sliznici. Ty tlumí sekreci vody vyvolanou zánětem, ale nemají vliv na bazální motilitu. Hrozí u něj méně sekundární zácpy.",
          "Nesprávně. Nifuroxazid je lokální střevní antiseptikum."
