      "    - **Prostaglandiny** (Dinoproston - PGE2, Carboprost - PGF2alpha, Misoprostol - PGE1): vyvolávají zrání děložního hrdla (rozrušení kolagenu) a stimulují silné kontrakce.",
      "    - **Námelové alkaloidy** (Methylergometrin): vyvolává dlouhotrvající, nefyziologické tonické kontrakce. Užívá se pouze k zástavě poporodního krvácení.",
      "  - Tokolytika (tlumí kontrakce):",
      "    - **Atosiban**: specifický antagonista oxytocinových a vasopresinových receptorů v děloze. Bezpečný.",
      "    - **Hexoprenalin**: $\\beta_2$-sympatomimetikum, relaxuje myometrium (vedlejší účinek: tachykardie, hypokalémie).",
      "    - **Nifedipin** (BVK): blokuje vstup vápníku do hladkého svalu dělohy.",
      "    - Síran hořečnatý ($MgSO_4$): antagonizuje vápník (neuroprotekce plodu, tokolýza)."
