    "pearl": "Inhibitory kalcineurinu (cyklosporin A, tacrolimus) vykazují akutní i chronickou nefrotoxicitu, která je paradoxně hlavním limitem jejich použití při transplantaci ledvin. Akutní toxicita je vyvolána spasmusem aferentní arterioly ledvin a je plně reverzibilní při snížení dávky pod kontrolou TDM. Chronická toxicita však vede k nevratnému poškození (intersticiální fibróze ledviny)!",
