          "Správně! Změna cílového proteinu PBP (na který se beta-laktamy vážou k inhibici stěny) způsobuje, že se na něj antibiotikum nedokáže přichytit. MRSA je proto rezistentní k penicilinům, cefalosporinům (kromě 5. generace) i karbapenemům.",
