          "Správně! Vankomycin podaný ústy se nevstřebává, což je v tomto případě ideální, protože dosahuje extrémně vysokých a účinných koncentrací přímo v lumen tlustého střeva, kde klostridia sídlí.",
          "Nesprávně. Penicilin G se v tlustém střevě nevyskytuje v dostatečné koncentraci a na C. difficile nepůsobí.",
