      "Co-amoxicilin (amoxicilin/klavulanát): kousnutí zvířetem, komplikované infekce močových a dýchacích cest.",
      "Piperacilin/tazobaktam (Tazocin): těžké nozokomiální infekce, sepse na JIP.",
