    "pearl": "U pacienta s akutní angínou vyvolanou virem Epstein-Barrové (infekční mononukleóza) je podání amoxicilinu spojeno s rozvojem těžkého toxoalergického makulopapulózního exantému u > 90 % případů. Nejedná se o pravou IgE alergii na peniciliny, ale o imunokomplexovou reakci vyvolanou interakcí viru s antibiotikem. Nenasazujte amoxicilin naslepo bez vyloučení mononukleózy!",
