      "Ceftriaxon (3. gen) má výjimečný poločas (cca 8 hodin), vylučuje se z 40 % žlučí a podává se pouze jednou denně (ideální pro ambulantní i.v. léčbu). Prochází skvěle přes HEB do likvoru u zánětů mening."
