      "  - **2. generace** (cefuroxim): vyrovnaný účinek GP a GN (H. influenzae, Klebsiella). Užití: infekce dýchacích cest.",
      "  - **3. generace** (ceftriaxon, cefotaxim - i.v., ceftazidim - antipseudomonádový): silný účinek na GN, odolné k běžným beta-laktamázám. Užití: těžké sepse, pneumonie, meningitidy.",
      "  - **4. generace** (cefepim): velmi široké spektrum (GP + GN + Pseudomonas). Vysoce odolný k chromozomálním beta-laktamázám AmpC.",
      "  - **5. generace** (ceftarolin): **jediný účinný na MRSA** (váže se na mutantní protein PBP2a)."
