      "Zástupci: Erythromycin (přírodní, nestabilní v kyselém pH), Klarithromycin, Azithromycin, Rokithromycin.",
      "Spektrum: grampozitivní koky, ale zejména **atypické (intracelulární) patogeny** (Chlamydia pneumoniae, Mycoplasma pneumoniae, Legionella pneumophila, Bordetella pertussis)."
