          "Nesprávně. Glifloziny samy o sobě hypoglykémii nezpůsobují, protože množství vyloučeného cukru klesá s klesající glykémií.",
          "Správně! Deriváty sulfonylurey 'tlačí' na beta-buňky, aby vylučovaly inzulin bez ohledu na hladinu glukózy v krvi. Pokud pacient vynechá jídlo, hrozí těžká a dlouhodobá hypoglykémie.",
