          "Nesprávně. Krystaly hydroxyapatitu nerozpouští (rozpouštění kosti dělají osteoklasty).",
          "Správně! RANKL je klíčovým cytokinem produkovaným osteoblasty k aktivaci osteoklastů. Jeho vyvázáním denosumab napodobuje přirozený osteoprotegerin (OPG).",
