          "Správně! Leukovorin (kyselina folinová) obchází enzym dihydrofolátreduktázu (kterou metotrexát zablokoval) a poskytuje buňkám hotový redukovaný folát pro syntézu purinů. Podává se s odstupem po MTX k 'záchraně' sliznic a kostní dřeně.",
          "Nesprávně. Dexrazoxan se podává jako kardioprotektivum k doxorubicinu.",
